 if(!hash_equals($_SESSION['website_csrf'],(string)($_POST['csrf']??''))){http_response_code(403);exit('Session invalide');}
 try{$action=(string)($_POST['action']??'');if($action==='inbox_status'){$status=(string)($_POST['status']??'');if(!in_array($status,['new','read','closed'],true))throw new InvalidArgumentException('Statut invalide.');$q=$db->prepare('UPDATE finea_website_inbox SET status=? WHERE id=?');$q->execute([$status,(int)($_POST['id']??0)]);}elseif($action==='media_upload'){if(!SiteContent::upload($db,$_FILES['media_file']??[]))throw new InvalidArgumentException('Sélectionnez une image.');}elseif($action==='unpublish'){$db->exec('UPDATE finea_website_content SET published_json=NULL,published_at=NULL WHERE id=1');}elseif(in_array($action,['save','publish'],true)){$content=SiteContent::fromPost($_POST);$db->beginTransaction();try{foreach(['hero_image','about_image'] as $key){$uploaded=SiteContent::upload($db,$_FILES[$key.'_file']??[]);if($uploaded!=='')$content[$key]=$uploaded;elseif(!empty($_POST[$key.'_remove']))$content[$key]='';if($content[$key]!==''){$check=$db->prepare('SELECT 1 FROM finea_website_media WHERE id=?');$check->execute([$content[$key]]);if(!$check->fetchColumn())throw new InvalidArgumentException('Image inconnue.');}}foreach(SiteContent::imageIds($content) as $id){$check=$db->prepare('SELECT 1 FROM finea_website_media WHERE id=?');$check->execute([$id]);if(!$check->fetchColumn())throw new InvalidArgumentException('Image inconnue.');}SiteContent::save($db,$content,$action==='publish');$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}}else{throw new InvalidArgumentException('Action inconnue.');}$_SESSION['website_flash']='Modification enregistrée.';header('Location: index.php');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}
}
$row=SiteContent::read($db);$data=SiteContent::decode($row['draft_json']??null,$brand);$published=!empty($row['published_json']);$flash=$_SESSION['website_flash']??'';unset($_SESSION['website_flash']);
